import csv

# Read the data
data = []
with open('outputs/t12_selected_matrix.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        indicator = row['DE1001V']
        print(f"city_id={row['city_id']}, year={row['year']}, DE1001V='{indicator}'")
        data.append({
            'city_id': row['city_id'],
            'city_name': row['city_name'],
            'year': row['year'],
            'indicator': indicator
        })

# Check for None vs empty string
for d in data:
    if d['indicator'] == '':
        print(f"Empty string")
    elif d['indicator'] == None:
        print(f"None")
